def last_values(pairs):
    """
    Return a list of the last value for each key, ordered by the first appearance of the key.
    """
    last = {}
    order = []
    for key, value in pairs:
        if key not in last:
            last[key] = value
            order.append(key)
        else:
            last[key] = value
    return [last[key] for key in order]
